/**
 * S58 (ADR-169): docs/reference/open-lists.md — every Open list as it stands, generated by `pnpm open:gen` from the
 * lists' own sources (data/convocation/formats/open/seeds.json, sim/open-lists.ts, data/convocation/formats/open/contributed.json) and
 * sync-tested: its sixty, its fifteen, its plan, its revisions by session, its mean on the table of record.
 */
import type { CardDef } from "@shandalar/cards";
import type { ComboPlan } from "@shandalar/agents";
import type { OpenList, OpenRevision } from "@shandalar/sim/open-lists";

export interface OpenReferenceInput {
  lists: readonly OpenList[];
  cards: Map<string, CardDef>;
  plans: readonly ComboPlan[];
  archived: Record<string, string>;
  /** `open:<key>` → the list's mean on the table of record. */
  means: Record<string, number>;
  amendments: Record<string, Record<string, number>>;
  revisions: readonly OpenRevision[];
  /** A contributed list's source line and its revision notes. */
  contributed: Record<string, { source?: string; revisions?: { session: string; note: string }[] }>;
  /** S59 (ADR-171): the matches table by list (data/convocation/formats/open/matches.json), when one has been recorded. */
  matches?: { when: string; matchesAPairing: number; byList: Record<string, { matches: number; gameOne: number; later: number; n: number }>; /** S71a: "a|b" → a's match wins against b (a draw a half) of n */ byPair?: Record<string, { w: number; n: number }> };
  /** S59: the sideboard guides, by list key. */
  guides?: readonly { key: string; rows: { in: string; n: number; out?: string[]; when: string[]; unless?: string[] }[]; only?: true }[];
  /** S63 (Part 2): the format this page is for (default the Open). A list's means and guide are keyed "<id>:<key>" outside the Open's guides. */
  format?: { id: string; title: string; sources: string };
}

/** ADR-170: the nonland cards (outside the restricted list's power) that more than half the active lists play. */
export function staples(lists: readonly OpenList[], cards: Map<string, CardDef>, skip: readonly string[] = []): { cardId: string; lists: number; copies: number }[] {
  const active = lists.filter((l) => !l.archived), by = new Map<string, { lists: number; copies: number }>();
  for (const l of active) for (const e of l.decklist) {
    if (cards.get(e.cardId)?.types.includes("Land") || skip.includes(e.cardId)) continue;
    const x = by.get(e.cardId) ?? { lists: 0, copies: 0 }; x.lists += 1; x.copies += e.count; by.set(e.cardId, x);
  }
  return [...by].filter(([, x]) => x.lists * 2 > active.length).map(([cardId, x]) => ({ cardId, ...x })).sort((a, b) => b.lists - a.lists || b.copies - a.copies || a.cardId.localeCompare(b.cardId));
}
/** The most-played nonland cards of the active lists (the watch list beside the staples). */
export function mostPlayed(lists: readonly OpenList[], cards: Map<string, CardDef>, skip: readonly string[], n: number): { cardId: string; lists: number; copies: number }[] {
  const active = lists.filter((l) => !l.archived), by = new Map<string, { lists: number; copies: number }>();
  for (const l of active) for (const e of l.decklist) {
    if (cards.get(e.cardId)?.types.includes("Land") || skip.includes(e.cardId)) continue;
    const x = by.get(e.cardId) ?? { lists: 0, copies: 0 }; x.lists += 1; x.copies += e.count; by.set(e.cardId, x);
  }
  return [...by].map(([cardId, x]) => ({ cardId, ...x })).sort((a, b) => b.lists - a.lists || b.copies - a.copies || a.cardId.localeCompare(b.cardId)).slice(0, n);
}

export function renderOpenListsReference(input: OpenReferenceInput, restricted: readonly string[]): string {
  const { lists, cards, plans, archived, means, amendments, revisions, contributed, matches, guides } = input;
  const fid = input.format?.id ?? "open", mk = (k: string) => `${fid}:${k}`, gk = (k: string) => (fid === "open" ? k : `${fid}:${k}`);
  const name = (id: string) => cards.get(id)?.name ?? id;
  const line = (xs: { cardId: string; count: number }[]) => xs.map((e) => `${e.count} ${name(e.cardId)}`).join(" · ");
  const delta = (d: Record<string, number>) => { const out = Object.entries(d).filter(([, n]) => n < 0).map(([c, n]) => `−${-n} ${c}`), ins = Object.entries(d).filter(([, n]) => n > 0).map(([c, n]) => `+${n} ${c}`); return `${out.join(" ")} → ${ins.join(" ")}`; };
  const L: string[] = [];
  L.push(`# ${input.format?.title ?? "The Open's lists"}`, "", input.format ? `*GENERATED by \`pnpm open:gen\` — do not edit by hand. ${input.format.sources}*` : "*GENERATED by `pnpm open:gen` — do not edit by hand. The lists live in code (ADR-169): the seeds in `data/convocation/formats/open/seeds.json`, their revisions in `packages/sim/src/open-lists.ts`, the lists contributed from play, the archive, the plans and the registered fifteens in `data/convocation/formats/open/contributed.json`.*", "");
  const active = lists.filter((l) => !l.archived);
  const mt = (k: string) => matches?.byList[k];
  const order = [...active].sort((a, b) => (mt(b.key)?.matches ?? means[mk(b.key)] ?? 0) - (mt(a.key)?.matches ?? means[mk(a.key)] ?? 0) || (means[mk(b.key)] ?? 0) - (means[mk(a.key)] ?? 0) || a.key.localeCompare(b.key));
  const signed = (x: number) => `${x >= 0 ? "+" : "−"}${Math.abs(x).toFixed(1)}`;
  L.push("## The table of record", "", `${active.length} active lists, the AI in both seats. **Game one** is a list's mean win rate against the other active lists on the registered sixties (the round-robin of record, \`formats/${fid}/means.json\`).${matches ? ` **Matches** is its best-of-three win rate — the figure the field's seat draw reads since S59 (${matches.matchesAPairing} matches a pairing, measured ${matches.when}; ADR-171): game one on the registered sixties, games two and three sideboarded. **After sideboarding** is its games-two-and-three rate less its game-one rate inside those matches.` : ""}`, "",
    matches ? "| list | deck | pilot | matches | game one | after sideboarding | fifteen |" : "| list | deck | pilot | game one |", matches ? "|---|---|---|---|---|---|---|" : "|---|---|---|---|");
  const fifteenOf = (l: OpenList) => (l.sideboard ? (guides?.some((g) => g.key === gk(l.key)) ? "registered, guided" : "registered") : "built");
  for (const l of order) { const x = mt(l.key), g1 = means[mk(l.key)] ?? "not yet measured"; L.push(matches ? `| ${l.name} | ${l.title} | ${l.archetype} | ${x ? x.matches.toFixed(1) : "—"} | ${g1} | ${x ? signed(x.later - x.gameOne) : "—"} | ${fifteenOf(l)} |` : `| ${l.name} | ${l.title} | ${l.archetype} | ${g1} |`); }
  L.push("", `Archived (kept in the data, out of the field): ${lists.filter((l) => l.archived).map((l) => l.name).join(", ") || "none"}.`, "");
  // S71a (the planner: the sub-table is a reporting lens, not a draw): the lists above 50 in matches, counted against one another only
  if (matches?.byPair) L.push(...subTable(order, matches as Required<NonNullable<OpenReferenceInput["matches"]>>));
  const st = staples(lists, cards, restricted);
  L.push("## Staples (ADR-170)", "", `Nonland cards outside the restricted list that more than half of the ${active.length} active lists play: ${st.length ? st.map((s) => `${name(s.cardId)} (${s.lists} lists, ${s.copies} copies)`).join("; ") : "none"}.`, "", `The most played: ${mostPlayed(lists, cards, restricted, 8).map((s) => `${name(s.cardId)} ${s.lists}`).join(" · ")}.`, "");
  // the active lists in the table's order; then the archive
  const archivedLists = lists.filter((l) => l.archived);
  for (const l of [...order, ...archivedLists]) {
    if (l === archivedLists[0]) L.push("# Archived lists", "", "*Kept in the data with their plans and their histories; out of the field, the round-robin and the tables.*", "");
    const def = (id: string) => cards.get(id)!;
    const lands = l.decklist.filter((e) => def(e.cardId).types.includes("Land")), creatures = l.decklist.filter((e) => !def(e.cardId).types.includes("Land") && def(e.cardId).types.includes("Creature")), other = l.decklist.filter((e) => !def(e.cardId).types.includes("Land") && !def(e.cardId).types.includes("Creature"));
    const n = (xs: { count: number }[]) => xs.reduce((a, e) => a + e.count, 0);
    L.push(`## ${l.name} — ${l.title}`, "", `\`${l.key}\` · ${l.archetype}${l.archived ? " · **archived**" : ` · game one ${means[mk(l.key)] ?? "not yet measured"}${mt(l.key) ? ` · matches ${mt(l.key)!.matches.toFixed(1)}` : ""}`}`, "");
    if (l.archived) L.push(`*Archived:* ${archived[l.key] ?? ""}`, "");
    L.push(`- **Lands (${n(lands)}):** ${line(lands)}`, `- **Creatures (${n(creatures)}):** ${line(creatures) || "—"}`, `- **Other (${n(other)}):** ${line(other) || "—"}`);
    L.push(l.sideboard ? `- **Its fifteen (registered):** ${line(l.sideboard)}` : "- **Its fifteen:** built by the field's builder for each seat (none registered).");
    const guide = guides?.find((g) => g.key === gk(l.key));
    const SHAPE: Record<string, string> = { creatureDeck: "a creature deck", fewLarge: "few, large creatures", control: "control", plan: "a combo plan", counters: "four or more counterspells", graveyard: "a graveyard deck", relics: "artifacts and enchantments", small: "many small creatures", someGraveyard: "some graveyard use", large: "many creatures of toughness three or more", hexproof: "four or more hexproof or shroud threats", killers: "eight or more cards that destroy or exile a creature" };
    if (guide) L.push(`- **Its sideboard guide**${guide.only ? " (the whole plan: the general rules do not run after it)" : " (then the general rules run on what is left)"}:`, ...guide.rows.map((r) => `  - against ${r.when.map((w) => SHAPE[w] ?? w).join(" or ")}${r.unless?.length ? ` (not ${r.unless.map((w) => SHAPE[w] ?? w).join(" or ")})` : ""}: ${r.n} ${name(r.in)} in${r.out?.length ? ` for ${r.out.map(name).join(", then ")}` : " for the lowest-rated cards"}`));
    else if (l.sideboard) L.push("- **Its sideboard guide:** none — the general rules sideboard it.");
    const plan = plans.find((p) => p.key === l.key);
    if (plan) L.push(`- **Its plan** (${plan.goal ?? "loop"}): ${(plan.pieces ?? [plan.piece]).map(name).join(" or ")}; set up by ${plan.setup.map((s) => name(s.card)).join(", ")}; started by ${plan.start.map((s) => name(s.card)).join(", ")}; dig ${plan.dig.map(name).join(", ") || "—"}; fuel ${plan.fuel.map(name).join(", ") || "—"}.`);
    const hist: string[] = [];
    const c = contributed[l.key];
    if (c?.source) hist.push(`contributed — ${c.source}`);
    if (!c && l.key !== "loop" && fid === "open") hist.push("a planner's seed list (2026-09-30)");
    if (l.key === "loop") hist.push("the twelfth list (S46): built from the Coin");
    if (amendments[l.key]) hist.push(`S46 and after: ${delta(amendments[l.key]!)}`);
    for (const r of revisions) if (r.lists[l.key]) hist.push(`${r.session}: ${delta(r.lists[l.key]!)}${r.why?.[l.key] ? ` (${r.why[l.key]})` : ""}`);
    for (const r of c?.revisions ?? []) hist.push(`${r.session}: ${r.note}`);
    L.push("- **History:**", ...hist.map((h) => `  - ${h}`), "");
  }
  return L.join("\n");
}

/** S71a: the top of a table read against itself — the active lists above 50 in matches, each one's match rate against
 * the others above 50 only (± 1.96 standard errors), beside its rate against the whole field; then the head-to-head. */
export function subTable(order: readonly OpenList[], matches: Required<NonNullable<OpenReferenceInput["matches"]>>): string[] {
  const top = order.filter((l) => (matches.byList[l.key]?.matches ?? 0) > 50);
  if (top.length < 3) return [];
  const among = (k: string) => { let w = 0, n = 0; for (const o of top) { if (o.key === k) continue; const p = matches.byPair[`${k}|${o.key}`]; if (p) { w += p.w; n += p.n; } } return { r: n ? (100 * w) / n : 0, e: n ? 196 * Math.sqrt(((w / n) * (1 - w / n)) / n) : 0 }; };
  const rows = top.map((l) => ({ l, ...among(l.key), field: matches.byList[l.key]!.matches })).sort((a, b) => b.r - a.r);
  const L = ["## Among the lists above 50 (S71a — a reading lens, not the draw)", "", `The ${top.length} lists above 50 in matches, counted against one another only. A list that gains most of its record from the bottom of the field falls here; the field's seat draw still reads the whole table.`, "",
    "| | list | among them | the whole field | change |", "|---|---|---|---|---|"];
  rows.forEach((x, i) => L.push(`| ${i + 1} | ${x.l.name} | ${x.r.toFixed(1)} ± ${x.e.toFixed(1)} | ${x.field.toFixed(1)} | ${x.r - x.field >= 0 ? "+" : "−"}${Math.abs(x.r - x.field).toFixed(1)} |`));
  L.push("", "Head to head (the row list's matches won, %):", "", `| | ${rows.map((x) => x.l.key).join(" | ")} |`, `|---|${rows.map(() => "---").join("|")}|`);
  for (const a of rows) L.push(`| **${a.l.key}** | ${rows.map((b) => { if (a === b) return "—"; const p = matches.byPair[`${a.l.key}|${b.l.key}`]; return p && p.n ? String(Math.round((100 * p.w) / p.n)) : "·"; }).join(" | ")} |`);
  L.push("");
  return L;
}
